function bindOnboarding(){let x;$('#onboardSwipe').addEventListener('touchstart',e=>x=e.touches[0].clientX,{passive:true});$('#onboardSwipe').addEventListener('touchend',e=>{if(Math.abs(e.changedTouches[0].clientX-x)>60){onboarding=Math.max(0,Math.min(2,onboarding+(e.changedTouches[0].clientX<x?1:-1)));render();}},{passive:true});}
function makeLayer(src,name) { return {id:crypto.randomUUID(),src,name,x:0,y:0,scale:1,rotation:0,opacity:1,brightness:0,contrast:1,mode:0,hidden:false,locked:false}; }
function createProject(kind,reference=null) { const id=crypto.randomUUID(); const doc={id,name:reference?.title||'Untitled Composition',kind,layers:reference?[makeLayer(reference.image,reference.title)]:[],grid:false,background:'#f4ecdd',offset:{x:0,y:0},zoom:1,updatedAt:Date.now(),favorite:false};write('project-'+id,doc);state.projects.unshift({id,name:doc.name,kind,modifiedAt:doc.updatedAt,favorite:false});saveState();closeModal();navigate('studio',id); }
function loadProject(id) { if(project?.id===id)return;const doc=read('project-'+id);if(!doc||!Array.isArray(doc.layers))throw Error('This composition could not be opened. Its saved files have been preserved.');project={...doc,dirty:false};selected=null;locked=false; }
