    const resize=()=>{for(const l of project.layers){const el=$(`[data-layer="${l.id}"]`);if(!el)continue;loadImage(l.src).then(img=>{if(!el.isConnected)return;const size=layerSize(l,field.clientWidth,field.clientHeight,img);el.style.width=size.w+'px';el.style.height=size.h+'px';});}};resize();const observer=new ResizeObserver(resize);observer.observe(field);studioObserver?.disconnect();studioObserver=observer;applyLayerStyles();
